int def scoreMajor(int:major, int:sample) {
    if (major == 0) {
        return 30;
    } else if (major * 100 < sample * 1) {
        return 20;
    } else if (major * 100 < sample * 3) {
        return 10;
    } else {
        return 0;
    }
}


int def scoreMinor(int:minor, int:sample) {
    if (minor == 0) {
        return 20;
    } else if (minor * 100 < sample * 3) {
        return 14;
    } else if (minor * 100 < sample * 5) {
        return 7;
    } else {
        return 0;
    }
}


int def scoreCertificate(boolean:provided) {
    if (provided) {
        return 15;
    } else {
        return 0;
    }
}


int def scoreAppearance(boolean:pass) {
    if (pass) {
        return 15;
    } else {
        return 0;
    }
}


int def scoreDimension(boolean:pass) {
    if (pass) {
        return 10;
    } else {
        return 0;
    }
}


int def scoreEnvironmental(boolean:compliant) {
    if (compliant) {
        return 10;
    } else {
        return 0;
    }
}


str def inspectionLevel(int:totalScore) {
    if (totalScore >= 90) {
        return "ACCEPT";
    } else if (totalScore >= 70) {
        return "CONDITIONAL";
    } else {
        return "REJECT";
    }
}
